 */
export function faqFuerLand(items, land, { markieren = false } = {}) {
  const l = landCode(land);
  return items.map((it) => {
    const basis = ohneSteuerung(it);
    if (l && it[l]) return { ...basis, ...it[l] };
    if (!it.nurDE) return basis;
    if (l === "DE") return basis;
    if (!l || markieren) {
      const text = typeof it.a === "string" ? it.a : it.aText;
      return {
        ...basis,
        a: (
          <>
            {it.a} <GiltFuer />
          </>
        ),
        ...(text ? { aText: text } : {}),
      };
    }
    return { q: it.q, a: nurDeText(l, it.nurDE === true ? undefined : it.nurDE) };
  });
