// Übersetzer Gruppe 1: Seite durchscrollen (Reveal auslösen) und in Kacheln je Bildschirmhöhe aufnehmen.
// Aufruf: node ue1-kacheln.mjs <basis> <ordner> <breiten> <pfad> [pfad …]
// Ausgabe: <ordner>/w<breite>-<name>-<nr>.png, Konsole: Status, Überlauf, Seitenfehler, Kachelanzahl.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
const [basis, out, breitenArg, ...pfade] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const ctx = await browser.newContext({ reducedMotion: "reduce" });
for (const w of breitenArg.split(",").map(Number)) {
  const h = w < 700 ? 844 : 900;
  const page = await ctx.newPage();
  await page.setViewportSize({ width: w, height: h });
  for (const pfad of pfade) {
    const fehler = [];
    const onE = (e) => fehler.push(String(e));
    page.on("pageerror", onE);
    try {
      const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 240000 });
      await page.locator("button", { hasText: /^(Nur notwendige|Necessary only)$/ }).first().click({ timeout: 3000 }).catch(() => {});
      await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 400) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 50)); } window.scrollTo(0, 0); });
      await page.waitForTimeout(700);
      const breite = await page.evaluate(() => document.documentElement.scrollWidth);
      const gesamt = await page.evaluate(() => document.documentElement.scrollHeight);
      const name = pfad.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "start";
      let n = 0;
      for (let y = 0; y < gesamt; y += h) {
        await page.screenshot({ path: `${out}/w${w}-${name}-${String(n).padStart(2, "0")}.png`, fullPage: true, clip: { x: 0, y, width: w, height: Math.min(h, gesamt - y) } });
        n++;
      }
      console.log(`w${w} ${pfad} status=${r?.status()} breite=${breite}${breite > w ? " UEBERLAUF" : ""} fehler=${fehler.length} kacheln=${n}`);
      fehler.slice(0, 3).forEach((f) => console.log("   ! " + f.slice(0, 200)));
    } catch (e) {
      console.log(`w${w} ${pfad} FEHLER ${String(e).slice(0, 160)}`);
    }
    page.off("pageerror", onE);
  }
  await page.close();
}
await browser.close();

