    "@context": "https://schema.org",
    "@type": "Service",
    name: "Terminbuchung ÖkoInvest",
    url: abs(PFAD),
    provider: { "@id": `${abs("/")}/#organization` },
    areaServed: ["DE", "AT", "CH"],
    availableChannel: { "@type": "ServiceChannel", serviceUrl: abs(PFAD) },
