                </ul>
              </nav>
            </div>
          </div>
        </div>
      </section>

      {/* ---------- Buchung ---------- */}
      <section id="buchung" aria-label="Termin buchen" className="relative scroll-mt-24 bg-sand-50 pb-16 md:pb-24">
        <div className="ov-container">
          <div className="relative -mt-16 grid gap-6 md:-mt-20 lg:grid-cols-[minmax(0,1fr)_300px] xl:grid-cols-[minmax(0,1fr)_320px] xl:gap-8">
