                      <span className="min-w-0">
                        <span className="block text-[14px] font-semibold leading-tight text-ink-900">{s.t}</span>
                        <span className="block text-[12.5px] leading-snug text-ink-600">{s.s}</span>
                      </span>
                    </li>
                  );
