                    { icon: CalendarCheck2, t: "Sofort bestätigt", s: "E-Mail mit Kalenderdatei (ICS)" },
                    { icon: RefreshCcw, t: "Flexibel bleiben", s: "Verschieben oder absagen per persönlichem Link" },
