// src/lib/sprache/gruppe1.test.mjs – Übersetzer-Gruppe 1 (Börse, Investoren, Unternehmen, Recht)
//
//   node --test src/lib/sprache/gruppe1.test.mjs
//
// - Register: übersetzte Seiten indexierbar, englische Rechtstexte übersetzt, aber noindex
//   (Vermerk index: false bis zur Freigabe durch die Rechtsabteilung) und nicht in der Sitemap.
// - Meldungen der Formulare: bekannte Prüfmeldungen englisch, unbekannte bleiben deutsch.
// - Formate: Eurobeträge und Termine im englischen Format.

import test from "node:test";
import assert from "node:assert/strict";
import { UEBERSETZT, uebersetzt, uebersetztIndexierbar } from "./seiten.js";
import { meldungFuer } from "./meldungen.js";
import { fmtEuro } from "./format.js";
import { TERMIN_ARTEN_EN, terminArt, zeitraumTextEn } from "./termine.js";
import { TERMIN_ARTEN } from "../plattform/termine/index.js";
import { alternates, fassungIndexierbar } from "../land/pfad.js";
import { abs } from "../../data/site.js";

const SEITEN = ["/investoren", "/projektboerse", "/projektboerse/anbieten", "/projektboerse/karte", "/bestandsanlagen", "/kontakt", "/termin", "/unternehmen", "/referenzen", "/warum-oekoinvest", "/prozess"];
const RECHT = ["/impressum", "/barrierefreiheit", "/datenschutz", "/nutzungsbedingungen", "/bedingungen/projektboerse", "/bedingungen/energiebeschaffung", "/bedingungen/lieferanten", "/bedingungen/banken"];

test("Gruppe 1: Seiten übersetzt und indexierbar, Exposés über das Muster", () => {
  for (const k of SEITEN) {
    assert.equal(uebersetzt(k), true, `${k} nicht übersetzt`);
    assert.equal(uebersetztIndexierbar(k), true, `${k} nicht indexierbar`);
    assert.equal(fassungIndexierbar(k, null, "en"), true, `${k}: englische Fassung nicht indexierbar`);
  }
  assert.equal(uebersetzt("/projektboerse/irgendein-projekt"), true, "Exposé-Muster /projektboerse/[slug]");
});

test("Gruppe 1: Rechtstexte übersetzt (kein Hinweis), aber noindex und ohne hreflang bis zur Freigabe", () => {
  for (const k of RECHT) {
    assert.equal(uebersetzt(k), true, `${k} nicht übersetzt`);
    assert.equal(UEBERSETZT[k].index, false, `${k}: Vermerk index: false fehlt`);
    assert.equal(uebersetztIndexierbar(k), false, `${k} darf noch nicht indexiert werden`);
    assert.equal(fassungIndexierbar(k, null, "en"), false, `${k}: englische Fassung indexierbar`);
    assert.deepEqual(alternates(k, null, { sprache: "en" }), { canonical: abs(`/en${k}`) }, `${k}: ohne Cluster`);
  }
});

test("Formularmeldungen: bekannte Meldungen englisch, Deutsch bleibt Deutsch", () => {
  assert.equal(meldungFuer("Bitte ausfüllen.", "en"), "Please fill in this field.");
  assert.equal(meldungFuer("Bitte ausfüllen.", "de"), "Bitte ausfüllen.");
  assert.equal(meldungFuer("Der Vorname ist zu kurz (mindestens 1 Zeichen).", "en"), "The first name is too short (at least 1 character).");
  assert.equal(meldungFuer("Die Nachricht ist zu lang (höchstens 5000 Zeichen).", "en"), "The message is too long (at most 5000 characters).");
  assert.match(meldungFuer("Deutsche Postleitzahlen haben 5 Ziffern, z. B. 86825. Liegt der Ort in Österreich oder der Schweiz? Dann bitte oben das Land ändern.", "en"), /^German postcodes have 5 digits, e\.g\. 86825\. Is the place in Austria or Switzerland\?/);
  assert.equal(meldungFuer("Postleitzahlen in der Schweiz haben 4 Ziffern, z. B. 8001.", "en"), "Swiss postcodes have 4 digits, e.g. 8001.");
  assert.equal(meldungFuer("Unbekannte Servermeldung", "en"), "Unbekannte Servermeldung");
  assert.equal(meldungFuer("", "en"), "");
});

test("Formate: Euro und Termine englisch", () => {
  assert.equal(fmtEuro(1234567.4, "en"), "€1,234,567");
  assert.equal(fmtEuro(1234567.4, "de"), "1.234.567 €");
  assert.match(zeitraumTextEn("2026-10-06T08:00:00Z", "2026-10-06T09:30:00Z"), /^Tue, 06 Oct 2026, 10:00–11:30 \(Vienna\/Berlin time\)$/);
  for (const id of Object.keys(TERMIN_ARTEN)) assert.ok(TERMIN_ARTEN_EN[id]?.label, `Terminart ${id} ohne englischen Namen`);
  assert.equal(terminArt(TERMIN_ARTEN.besichtigung, "besichtigung", "en").dauer, TERMIN_ARTEN.besichtigung.dauer, "Dauer bleibt aus der Konfiguration");
  assert.equal(terminArt(TERMIN_ARTEN.besichtigung, "besichtigung", "de").label, TERMIN_ARTEN.besichtigung.label);
});

// src/lib/sprache/meldungen.js – englische Fassung der Formular- und Prüfmeldungen
//
// Die Prüfregeln (src/components/Portal/Bedienung/pruefung.js, src/components/formular/useFormular.js)
// und die Formulare erzeugen ihre Meldungen auf Deutsch – auch serverseitige Antworten. Auf englischen
// Seiten übersetzt meldungFuer() die bekannten Meldungen an EINER Stelle (useFormular, FormFehler),
// statt jede Regel doppelt zu führen. Unbekannte Meldungen bleiben deutsch (Rückfall wie im Wörterbuch).
//
//   meldungFuer("Bitte ausfüllen.", "en") → "Please fill in this field."
//
// Ergänzen: neues Paar [Muster, englischer Text | (treffer) => Text] in MUSTER.

const WAS = {
  "Der Vorname": "The first name",
  "Der Nachname": "The last name",
  "Die Nachricht": "The message",
  Eingabe: "The entry",
  "Der Name": "The name",
  "Die Bezeichnung": "The name",
  "Der Titel": "The title",
  "Die Beschreibung": "The description",
  Wert: "The value",
  Minimum: "The minimum",
};
const was = (w) => WAS[w] || w;
const zahl = (s) => String(s).replace(",", ".");

const MUSTER = [
  [/^Bitte ausfüllen\.$/, "Please fill in this field."],
  [/^Bitte geben Sie Ihren Vornamen an\.$/, "Please enter your first name."],
  [/^Bitte geben Sie Ihren Nachnamen an\.$/, "Please enter your last name."],
  [/^Bitte geben Sie Ihren Namen an\.$/, "Please enter your name."],
  [/^Bitte geben Sie Ihre E-Mail-Adresse an.*$/, "Please enter your e-mail address, e.g. name@company.com."],
  [/^Bitte geben Sie Ihr Unternehmen an\.$/, "Please enter your company."],
  [/^(.+) ist zu kurz \(mindestens (\d+) Zeichen\)\.$/, (_, w, n) => `${was(w)} is too short (at least ${n} character${n === "1" ? "" : "s"}).`],
  [/^(.+) ist zu lang \(höchstens (\d+) Zeichen\)\.$/, (_, w, n) => `${was(w)} is too long (at most ${n} character${n === "1" ? "" : "s"}).`],
  [/^Deutsche Postleitzahlen haben 5 Ziffern.*?(Liegt der Ort in Österreich oder der Schweiz\?.*)?$/, (_, z) => `German postcodes have 5 digits, e.g. 86825.${z ? " Is the place in Austria or Switzerland? Then please change the country above." : ""}`],
  [/^Postleitzahlen in Österreich haben 4 Ziffern.*?(Liegt der Ort in Deutschland\?.*)?$/, (_, z) => `Austrian postcodes have 4 digits, e.g. 5020.${z ? " Is the place in Germany? Then please change the country above." : ""}`],
  [/^Postleitzahlen in der Schweiz haben 4 Ziffern.*?(Liegt der Ort in Deutschland\?.*)?$/, (_, z) => `Swiss postcodes have 4 digits, e.g. 8001.${z ? " Is the place in Germany? Then please change the country above." : ""}`],
  [/^Bitte eine gültige Postleitzahl angeben\.$/, "Please enter a valid postcode."],
  [/^Bitte nur eine Zahl eingeben(?: \(in (.+)\))?, z\. B\. 12,5\.$/, (_, e) => `Please enter a number only${e ? ` (in ${e})` : ""}, e.g. 12.5.`],
  [/^(.+) muss mindestens (\S+)(?: (.+))? betragen\.$/, (_, w, n, e) => `${was(w)} must be at least ${zahl(n)}${e ? ` ${e}` : ""}.`],
  [/^(.+) darf höchstens (\S+)(?: (.+))? betragen – bitte Eingabe prüfen\.$/, (_, w, n, e) => `${was(w)} may be at most ${zahl(n)}${e ? ` ${e}` : ""} – please check your entry.`],
  [/^Bitte eine Telefonnummer mit Vorwahl angeben.*$/, "Please enter a phone number with area code, e.g. +49 8245 123456."],
  [/^Das sieht nicht nach einer E-Mail-Adresse aus.*$/, "That does not look like an e-mail address – please check (e.g. name@company.com)."],
  [/^(.+) ist größer als der Höchstwert – bitte tauschen\.$/, (_, w) => `${was(w)} is greater than the maximum – please swap them.`],
  [/^Für den gewünschten Rückruf brauchen wir Ihre Telefonnummer\.$/, "We need your phone number for the requested call-back."],
  [/^Die Eingaben stimmen nicht überein\.$/, "The entries do not match."],
  [/^Bitte bestätigen Sie diesen Punkt\.$/, "Please confirm this point."],
  [/^Bitte wählen Sie mindestens eine Option\.$/, "Please select at least one option."],
  [/^Bitte wählen Sie (?:einen|eine) .+\.$/, "Please make a selection."],
  [/^Die Verbindung ist gerade gestört.*$/, "The connection is currently disrupted. Your details are kept – please try again in a moment."],
  [/^Senden fehlgeschlagen\..*$/, "Sending failed. Your details are kept – please try again."],
  [/^Senden fehlgeschlagen$/, "Sending failed"],
  [/^Zu viele Anfragen.*$/, "Too many requests. Please wait a moment and try again."],
];

/** Meldung in der Sprache der Seite (bekannte Meldungen; sonst unverändert). */
export function meldungFuer(text, sprache) {
  if (sprache !== "en" || typeof text !== "string" || !text) return text;
  for (const [re, en] of MUSTER) {
    const m = text.match(re);
    if (m) return typeof en === "function" ? en(...m) : en;
  }
  return text;
}

